377	/**
378	 * A claim's figures, as the screen shows them. Its rate figure: the figure its person's last
379	 * statement bound it to (OPEN or PENDING alike; the floored figure), else the greater of the sheet's
380	 * floor in force on its date and its amount times its grade's rate in force on its date (of the rates
381	 * that apply to it: a forward-only rate only to claims added after it was saved), divided by 100 and
382	 * rounded to two decimals. Its live due: that floored rate figure plus its late charge (worked out on
383	 * the floored figure); a correction, a negative amount, has no floor and no late charge. A settled
384	 * claim's due stays as it was fixed. Null for n/a (no floor applies to n/a). Every rounding of a
385	 * claim's live figures is by the sheet's policy date ({@link Settings#rounding}): half up when the
386	 * claim is dated before it, half to even on or after; a correction rounds by the date of the claim
387	 * it corrects.
388	 */
389	public final class ClaimFigure {
390	    private ClaimFigure() {}
391	
392	    /** The claim's rate figure: its bound figure when a statement bound it, else its live rate figure floored. */
393	    public static BigDecimal of(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
394	        if (claim.isBound()) return claim.getStatedDue();
395	        return floor(claim, live(claim, rates, grade, settings, today), settings);
396	    }
397	
398	    /** A live rate figure held to at least the floor in force on the claim's date; a correction has no floor. Null for n/a. */
399	    public static BigDecimal floor(Claim claim, BigDecimal figure, Settings settings) {
400	        if (figure == null || claim.isCorrection()) return figure;
401	        return figure.max(settings.floorOn(claim.getDate()));
402	    }
403	
404	    /** The claim's amount at its grade's rate on its date, before any floor or late charge. */
405	    public static BigDecimal live(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
406	        RoundingMode mode = rounding(claim, settings, today);
407	        return Rate.inForce(rates, grade, claim.getDate(), claim.getId())
408	                .map((pct) -> times(claim.getAmount(), pct, mode))
409	                .orElse(null);
410	    }
411	
412	    /** The due on a floored rate figure ({@link #floor}) with the late charge on it. Null for n/a. */
413	    public static BigDecimal due(BigDecimal figure, BigDecimal late) {
414	        return figure == null ? null : figure.add(late);
415	    }
416	
417	    /** How the claim's live figures round, by the date it rounds by and the sheet's policy date. */
418	    public static RoundingMode rounding(Claim claim, Settings settings, LocalDate today) {
419	        return settings.rounding(claim.getRoundDate(), today);
420	    }
421	
422	    /**
423	     * The claim's due as the screen shows it: the due fixed when it was settled, else its live due:
424	     * its floored rate figure ({@link #of}) plus the late charge an OPEN or PENDING claim gains on that
425	     * figure while overdue on {@code today}. Null for n/a.
426	     */
427	    public static BigDecimal withLate(Claim claim, List<Rate> rates, String grade, Settings settings,
428	            LocalDate today) {
429	        if (claim.getSettledDue() != null) return claim.getSettledDue();
430	        BigDecimal figure = of(claim, rates, grade, settings, today);
431	        return figure == null ? null : due(figure, late(claim, figure, grade, settings, today));
432	    }
433	
434	    /**
435	     * The late charge on a figure: for an OPEN or PENDING claim past its due-by (fixed when it was made)
436	     * plus the grace days of its grade ({@code grade}, the one in force on its date) on its date
437	     * ({@link Settings#overdueFrom}) on {@code today}, for every full 30 days it is overdue the
438	     * sheet's late percent in force on that boundary date (that day plus 30, 60, 90 ... days) of the figure plus the
439	     * charges of the boundaries before it (compounding), each rounded to two
440	     * decimals as the claim rounds, added up; else 0.00 (as for a claim deferred on today, or one whose late charge
441	     * a steward waived, whatever its overdue state). While a statement binds it with a late charge, that
442	     * charge, whatever the sheet's today; else it follows the sheet's today until the claim is settled.
443	     */
444	    public static BigDecimal late(Claim claim, BigDecimal figure, String grade, Settings settings, LocalDate today) {
445	        if (!claim.isOpen() || claim.isDeferredOn(today)) return BigDecimal.ZERO.setScale(2);
446	        if (claim.isBound() && claim.getStatedLate() != null && !claim.isWaived()) return claim.getStatedLate();
447	        return lateAsOpen(claim, figure, grade, settings, today);
448	    }
449	
450	    /** The late charge on a figure as {@link #late} reads it for an open claim, whatever the claim's status. */
451	    public static BigDecimal lateAsOpen(Claim claim, BigDecimal figure, String grade, Settings settings,
452	            LocalDate today) {
453	        BigDecimal none = BigDecimal.ZERO.setScale(2);
454	        if (figure == null || claim.isCorrection() || claim.isWaived()) return none;
455	        LocalDate from = settings.overdueFrom(claim.getDueBy(), grade, claim.getDate());
456	        long overdue = ChronoUnit.DAYS.between(from, today);
457	        long periods = overdue > 0 ? overdue / 30 : 0;
458	        RoundingMode mode = rounding(claim, settings, today);
459	        BigDecimal charge = none;
460	        for (long k = 1; k <= periods; k++) {
461	            BigDecimal pct = settings.latePctOn(from.plusDays(30 * k));
462	            if (pct.signum() != 0) charge = charge.add(times(figure.add(charge), pct, mode));
463	        }
464	        return charge;
465	    }
466	
467	    /** The amount times the percent, divided by 100 and rounded to two decimals. */
468	    private static BigDecimal times(BigDecimal amount, BigDecimal pct, RoundingMode mode) {
469	        return amount.multiply(pct).divide(BigDecimal.valueOf(100), 2, mode);
470	    }
471	}
472	package net.officefloor.hq.app.claim;
473	
474	import net.officefloor.hq.app.period.Period;
475	import net.officefloor.hq.app.period.PeriodRepository;
476	import net.officefloor.hq.app.setting.Settings;
477	import net.officefloor.hq.app.sheet.Sheet;
478	
479	/**
480	 * The number a claim being opened takes: the next within the fiscal year of its due-by, in the
481	 * sequence the sheet's tree shares (<FY>-<n>), or, while the sheet's period
482	 * numbering from is set and its today is on or after it, the next within the claim's period (the one containing its due-by)
483	 * (<period name>-<n>), or X-<n> when the claim is in no period.
484	 */
485	public final class ClaimNumbers {
486	    private ClaimNumbers() {}
487	
488	    public static String next(Sheet sheet, Claim claim, Settings settings, PeriodRepository periods, ClaimRepository claims) {
489	        if (!settings.numbersByPeriod(sheet.today())) {
490	            String fiscalYear = settings.fiscalYearOf(claim.getDueBy());
491	            return fiscalYear + "-" + claims.nextNumberInFiscalYear(sheet.id(), fiscalYear);
492	        }
493	        Period period = periods.findAll(sheet.id()).stream()
494	                .filter((p) -> p.contains(claim.getDueBy())).findFirst().orElse(null);
495	        if (period == null) return "X-" + claims.nextNumberIn(sheet.id(), "");
496	        return period.name() + "-" + claims.nextNumberIn(sheet.id(), period.name());
497	    }
498	}
499	package net.officefloor.hq.app.claim;
500	
501	/**
502	 * A claim's status. It starts as DRAFT, is opened (OPEN) and then settled (SETTLED). A clerk's
503	 * settle above the clerk limit makes it PENDING instead, until a steward approves it (SETTLED) or
504	 * rejects it (back to OPEN). A claim whose due is above the review threshold in force on its date goes
505	 * to REVIEW instead of OPEN when it is opened, unnumbered, until a steward reviews it (OPEN, numbered then).
506	 * A DRAFT, REVIEW, OPEN or PENDING claim can be voided (VOID); a SETTLED one
507	 * too, by a steward within days of its settlement ({@link VoidClaim}). VOID is final. A DRAFT claim can be deleted
508	 * (DELETED), and made a DRAFT again by a restore on the sheet's today it was deleted ({@link RestoreClaim}). Only OPEN, PENDING and SETTLED claims count toward any total.
509	 */
510	public enum ClaimStatus {
511	    DRAFT(null), REVIEW("CLAIM_REVIEW"), OPEN("CLAIM_OPENED"), PENDING("CLAIM_PENDING"), SETTLED("CLAIM_SETTLED"), VOID("CLAIM_VOIDED"),
512	    DELETED("CLAIM_DELETED");
513	
514	    private final String auditEvent;
515	
516	    ClaimStatus(String auditEvent) {
517	        this.auditEvent = auditEvent;
518	    }
519	
520	    /** The audit event written when a claim moves into this status. */
521	    public String auditEvent() {
522	        return auditEvent;
523	    }
524	
525	    /** Whether a claim in this status may move to {@code next}. */
526	    public boolean canMoveTo(ClaimStatus next) {
527	        return switch (next) {
528	            case REVIEW -> this == DRAFT;
529	            case OPEN -> this == DRAFT || this == REVIEW;
530	            case PENDING -> this == OPEN;
531	            case SETTLED -> this == OPEN;
532	            case VOID -> this == DRAFT || this == REVIEW || this == OPEN || this == PENDING || this == SETTLED;
533	            case DELETED -> this == DRAFT;
534	            case DRAFT -> this == DELETED;
535	        };
536	    }
537	}
538	package net.officefloor.hq.app.claim;
539	
540	import java.util.List;
541	
542	/**
543	 * A claim, as the screen reads it: its amount with two decimals, its date as yyyy-MM-dd and its
544	 * status, its number ("" when it has none), and its due as fixed when it was settled ("" while
545	 * its due is live), and who opened it ("" until it is opened); whether its person's last
546	 * statement bound it, and the figure it was bound to ("" when not stated, n/a when it had none);
547	 * and the number of the claim it corrects ("" when it is no correction); and the date its figures
548	 * round by (a correction's is the date of the claim it corrects); and its due-by as yyyy-MM-dd, fixed
549	 * when it was made; and its status log, oldest first, one line per status it has had as
550	 * {@code <STATUS> by <user> on <date> due=<due>}; and the date it is deferred until as yyyy-MM-dd
551	 * ("" when it was never deferred; it is deferred only while OPEN and the sheet's today is before it);
552	 * and how many proofs it has had added; and the number of the claim it was split off ("" when none);
553	 * and the user whose open editor locks it on the sheet's today ("" when no one's does);
554	 * and whether it was added while its period was soft-closed; and the last sheet's today it was reminded
555	 * as yyyy-MM-dd ("" when never); and its external reference ("" when none); and its tags, sorted (none: empty); and the reason it was voided with ("" when none); and its comments, oldest first, as
556	 * {@code <user> on <date>: <text>}; and the number of the bulk settle batch that settled it ("" when none did);
557	 * and its lines, oldest first, as {@code <label> <qty> x <unit>}; and its review day, the sheet's today when it
558	 * went to REVIEW, as yyyy-MM-dd ("" when it never did); and whether a steward waived its late charge; and the
559	 * late charge its statement bound it to with its figure ("" when none is bound); and how many of its proofs are
560	 * receipts and how many photos; and whether it is held.
561	 */
562	public record ClaimResponse(String id, String personId, String amount, String date, String note,
563	        String status, String number, String due, String openedBy, boolean stated,
564	        String statedDue, String corrects, String roundDate, String dueBy, List<String> log, String deferredUntil,
565	        int proofs, String splitFrom, String lockedBy, boolean lateEntry, String remindedOn, String ref,
566	        List<String> tags, String voidReason, List<String> comments, String batch, List<String> lines, String reviewOn, boolean waived,
567	        String statedLate, int proofReceipts, int proofPhotos, boolean held) {
568	    public static ClaimResponse from(Claim claim) {
569	        return from(claim, List.of(), List.of(), List.of());
570	    }
571	
572	    public static ClaimResponse from(Claim claim, List<String> log, List<String> comments, List<String> lines) {
573	        return new ClaimResponse(String.valueOf(claim.getId()), String.valueOf(claim.getPersonId()),
574	                claim.getAmount().toPlainString(), claim.getDate().toString(), claim.getNote(),
575	                claim.getStatus().name(),
576	                claim.getNumber() == null ? "" : claim.getNumber(),
577	                claim.getSettledDue() == null ? "" : claim.getSettledDue().toPlainString(),
578	                claim.getOpenedBy() == null ? "" : claim.getOpenedBy(),
579	                claim.isStated(),
580	                !claim.isStated() ? "" : claim.getStatedDue() == null ? "n/a" : claim.getStatedDue().toPlainString(),
581	                claim.getCorrects() == null ? "" : claim.getCorrects(),
582	                claim.getRoundDate().toString(), claim.getDueBy().toString(), log,
583	                claim.getDeferredUntil() == null ? "" : claim.getDeferredUntil().toString(),
584	                claim.getProofs(),
585	                claim.getSplitFrom() == null ? "" : claim.getSplitFrom(),
586	                claim.getLockedBy() == null ? "" : claim.getLockedBy(),
587	                claim.isLateEntry(),
588	                claim.getRemindedOn() == null ? "" : claim.getRemindedOn().toString(),
589	                claim.getRef() == null ? "" : claim.getRef(),
590	                claim.tagList(),
591	                claim.getVoidReason() == null ? "" : claim.getVoidReason(),
592	                comments,
593	                claim.getSettleBatch() == null ? "" : String.valueOf(claim.getSettleBatch()),
594	                lines,
595	                claim.getReviewOn() == null ? "" : claim.getReviewOn().toString(),
596	                claim.isWaived(),
597	                claim.getStatedLate() == null ? "" : claim.getStatedLate().toPlainString(),
598	                claim.getProofReceipts(), claim.getProofPhotos(), claim.isHeld());
599	    }
600	}
