package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.List;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.setting.Settings;

/**
 * A claim's figures, as the screen shows them. Its rate figure: the figure its person's last
 * statement bound it to (OPEN or PENDING alike; the floored figure), else the greater of the sheet's
 * floor in force on its date and its amount times its grade's rate in force on its date (of the rates
 * that apply to it: a forward-only rate only to claims added after it was saved), divided by 100 and
 * rounded to two decimals. Its live due: that floored rate figure plus its late charge (worked out on
 * the floored figure); a correction, a negative amount, has no floor and no late charge. A settled
 * claim's due stays as it was fixed. Null for n/a (no floor applies to n/a). Every rounding of a
 * claim's live figures is by the sheet's policy date ({@link Settings#rounding}): half up when the
 * claim is dated before it, half to even on or after; a correction rounds by the date of the claim
 * it corrects.
 */
public final class ClaimFigure {
    private ClaimFigure() {}

    /** The claim's rate figure: its bound figure when a statement bound it, else its live rate figure floored. */
    public static BigDecimal of(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
        if (claim.isBound()) return claim.getStatedDue();
        return floor(claim, live(claim, rates, grade, settings, today), settings);
    }

    /** A live rate figure held to at least the floor in force on the claim's date; a correction has no floor. Null for n/a. */
    public static BigDecimal floor(Claim claim, BigDecimal figure, Settings settings) {
        if (figure == null || claim.isCorrection()) return figure;
        return figure.max(settings.floorOn(claim.getDate()));
    }

    /** The claim's amount at its grade's rate on its date, before any floor or late charge. */
    public static BigDecimal live(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
        RoundingMode mode = rounding(claim, settings, today);
        return Rate.inForce(rates, grade, claim.getDate(), claim.getId())
                .map((pct) -> times(claim.getAmount(), pct, mode))
                .orElse(null);
    }

    /** The due on a floored rate figure ({@link #floor}) with the late charge on it. Null for n/a. */
    public static BigDecimal due(BigDecimal figure, BigDecimal late) {
        return figure == null ? null : figure.add(late);
    }

    /** How the claim's live figures round, by the date it rounds by and the sheet's policy date. */
    public static RoundingMode rounding(Claim claim, Settings settings, LocalDate today) {
        return settings.rounding(claim.getRoundDate(), today);
    }

    /**
     * The claim's due as the screen shows it: the due fixed when it was settled, else its live due:
     * its floored rate figure ({@link #of}) plus the late charge an OPEN or PENDING claim gains on that
     * figure while overdue on {@code today}. Null for n/a.
     */
    public static BigDecimal withLate(Claim claim, List<Rate> rates, String grade, Settings settings,
            LocalDate today) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        BigDecimal figure = of(claim, rates, grade, settings, today);
        return figure == null ? null : due(figure, late(claim, figure, grade, settings, today));
    }

    /**
     * The late charge on a figure: for an OPEN or PENDING claim past its due-by (fixed when it was made)
     * plus the grace days of its grade ({@code grade}, the one in force on its date) on its date
     * ({@link Settings#overdueFrom}) on {@code today}, for every full 30 days it is overdue the
     * sheet's late percent in force on that boundary date (that day plus 30, 60, 90 ... days) of the figure plus the
     * charges of the boundaries before it (compounding), each rounded to two
     * decimals as the claim rounds, added up; else 0.00 (as for a claim deferred on today, or one whose late charge
     * a steward waived, whatever its overdue state). While a statement binds it with a late charge, that
     * charge, whatever the sheet's today; else it follows the sheet's today until the claim is settled.
     */
    public static BigDecimal late(Claim claim, BigDecimal figure, String grade, Settings settings, LocalDate today) {
        if (!claim.isOpen() || claim.isDeferredOn(today)) return BigDecimal.ZERO.setScale(2);
        if (claim.isBound() && claim.getStatedLate() != null && !claim.isWaived()) return claim.getStatedLate();
        return lateAsOpen(claim, figure, grade, settings, today);
    }

    /** The late charge on a figure as {@link #late} reads it for an open claim, whatever the claim's status. */
    public static BigDecimal lateAsOpen(Claim claim, BigDecimal figure, String grade, Settings settings,
            LocalDate today) {
        BigDecimal none = BigDecimal.ZERO.setScale(2);
        if (figure == null || claim.isCorrection() || claim.isWaived()) return none;
        LocalDate from = settings.overdueFrom(claim.getDueBy(), grade, claim.getDate());
        long overdue = ChronoUnit.DAYS.between(from, today);
        long periods = overdue > 0 ? overdue / 30 : 0;
        RoundingMode mode = rounding(claim, settings, today);
        BigDecimal charge = none;
        for (long k = 1; k <= periods; k++) {
            BigDecimal pct = settings.latePctOn(from.plusDays(30 * k));
            if (pct.signum() != 0) charge = charge.add(times(figure.add(charge), pct, mode));
        }
        return charge;
    }

    /** The amount times the percent, divided by 100 and rounded to two decimals. */
    private static BigDecimal times(BigDecimal amount, BigDecimal pct, RoundingMode mode) {
        return amount.multiply(pct).divide(BigDecimal.valueOf(100), 2, mode);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * The number a claim being opened takes: the next within the fiscal year of its due-by, in the
 * sequence the sheet's tree shares (<FY>-<n>), or, while the sheet's period
 * numbering from is set and its today is on or after it, the next within the claim's period (the one containing its due-by)
 * (<period name>-<n>), or X-<n> when the claim is in no period.
 */
public final class ClaimNumbers {
    private ClaimNumbers() {}

    public static String next(Sheet sheet, Claim claim, Settings settings, PeriodRepository periods, ClaimRepository claims) {
        if (!settings.numbersByPeriod(sheet.today())) {
            String fiscalYear = settings.fiscalYearOf(claim.getDueBy());
            return fiscalYear + "-" + claims.nextNumberInFiscalYear(sheet.id(), fiscalYear);
        }
        Period period = periods.findAll(sheet.id()).stream()
                .filter((p) -> p.contains(claim.getDueBy())).findFirst().orElse(null);
        if (period == null) return "X-" + claims.nextNumberIn(sheet.id(), "");
        return period.name() + "-" + claims.nextNumberIn(sheet.id(), period.name());
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim's status. It starts as DRAFT, is opened (OPEN) and then settled (SETTLED). A clerk's
 * settle above the clerk limit makes it PENDING instead, until a steward approves it (SETTLED) or
 * rejects it (back to OPEN). A claim whose due is above the review threshold in force on its date goes
 * to REVIEW instead of OPEN when it is opened, unnumbered, until a steward reviews it (OPEN, numbered then).
 * A DRAFT, REVIEW, OPEN or PENDING claim can be voided (VOID); a SETTLED one
 * too, by a steward within days of its settlement ({@link VoidClaim}). VOID is final. A DRAFT claim can be deleted
 * (DELETED), and made a DRAFT again by a restore on the sheet's today it was deleted ({@link RestoreClaim}). Only OPEN, PENDING and SETTLED claims count toward any total.
 */
public enum ClaimStatus {
    DRAFT(null), REVIEW("CLAIM_REVIEW"), OPEN("CLAIM_OPENED"), PENDING("CLAIM_PENDING"), SETTLED("CLAIM_SETTLED"), VOID("CLAIM_VOIDED"),
    DELETED("CLAIM_DELETED");

    private final String auditEvent;

    ClaimStatus(String auditEvent) {
        this.auditEvent = auditEvent;
    }

    /** The audit event written when a claim moves into this status. */
    public String auditEvent() {
        return auditEvent;
    }

    /** Whether a claim in this status may move to {@code next}. */
    public boolean canMoveTo(ClaimStatus next) {
        return switch (next) {
            case REVIEW -> this == DRAFT;
            case OPEN -> this == DRAFT || this == REVIEW;
            case PENDING -> this == OPEN;
            case SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == REVIEW || this == OPEN || this == PENDING || this == SETTLED;
            case DELETED -> this == DRAFT;
            case DRAFT -> this == DELETED;
        };
    }
}
