135	        return value == null || value.isEmpty() ? null : Integer.valueOf(value);
136	    }
137	
138	    /**
139	     * The day a claim's overdue count starts from: its due-by plus the grace days of its grade (the
140	     * one in force on its date) in force on its date, or its due-by when that grade has none. A
141	     * claim is overdue when this is before the sheet's today, and its late charge's 30-day
142	     * boundaries are counted from it.
143	     */
144	    public LocalDate overdueFrom(LocalDate dueBy, String grade, LocalDate date) {
145	        Integer grace = grade == null ? null : gradeGraceOn(grade, date);
146	        return grace == null ? dueBy : dueBy.plusDays(grace);
147	    }
148	
149	    /** A sheet's floor until it is set. */
150	    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");
151	
152	    /** A sheet's terms until they are set. */
153	    public static final int DEFAULT_TERMS = 14;
154	
155	    /** A sheet's late percent until it is set. */
156	    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");
157	
158	    /** The value of a key in force on a date: null when none is recorded on or before it, '' for none. */
159	    public String valueOn(String key, LocalDate date) {
160	        NavigableMap<LocalDate, String> values = dated.get(key);
161	        if (values == null || date == null) return null;
162	        Map.Entry<LocalDate, String> entry = values.floorEntry(date);
163	        return entry == null ? null : entry.getValue();
164	    }
165	
166	    private BigDecimal figureOn(String key, LocalDate date) {
167	        String value = valueOn(key, date);
168	        return value == null || value.isEmpty() ? null : new BigDecimal(value).setScale(2);
169	    }
170	
171	    /** The floor in force on a date. */
172	    public BigDecimal floorOn(LocalDate date) {
173	        BigDecimal floor = figureOn(FLOOR, date);
174	        return floor != null ? floor : DEFAULT_FLOOR;
175	    }
176	
177	    /** The late percent in force on a date. */
178	    public BigDecimal latePctOn(LocalDate date) {
179	        BigDecimal pct = figureOn(LATE_PCT, date);
180	        return pct != null ? pct : DEFAULT_LATE_PCT;
181	    }
182	
183	    /** The sheet's terms in force on a date. */
184	    public int termsOn(LocalDate date) {
185	        String value = valueOn(TERMS, date);
186	        return value == null || value.isEmpty() ? DEFAULT_TERMS : Integer.parseInt(value);
187	    }
188	
189	    /** A grade's own terms in force on a date, or null when it takes the sheet's. */
190	    public Integer gradeTermsOn(String grade, LocalDate date) {
191	        String value = valueOn(gradeTermsKey(grade), date);
192	        return value == null || value.isEmpty() ? null : Integer.valueOf(value);
193	    }
194	
195	    /** The terms of a person's claim made on a date (the sheet's today then): their own in force then, else their grade's then, else the sheet's. */
196	    public int termsFor(net.officefloor.hq.app.person.Person person, LocalDate date) {
197	        Integer own = person.termsOn(date);
198	        return own != null ? own : termsFor(person.gradeOn(date), date);
199	    }
200	
201	    /** The terms of a grade on a date: its own, else the sheet's. */
202	    public int termsFor(String grade, LocalDate date) {
203	        Integer own = gradeTermsOn(grade, date);
204	        return own != null ? own : termsOn(date);
205	    }
206	
207	    /** The key of a grade's own clerk limit. */
208	    public static String gradeClerkLimitKey(String grade) {
209	        return "clerk-limit-" + grade;
210	    }
211	
212	    /** A grade's own clerk limit in force on a date, or null when it has none. */
213	    public BigDecimal gradeClerkLimitOn(String grade, LocalDate date) {
214	        return figureOn(gradeClerkLimitKey(grade), date);
215	    }
216	
217	    /** The clerk limit of a grade in force on a date: the grade's own when it has one, else the sheet's (null: no limit). */
218	    public BigDecimal clerkLimitFor(String grade, LocalDate date) {
219	        BigDecimal own = grade == null ? null : gradeClerkLimitOn(grade, date);
220	        return own != null ? own : clerkLimitOn(date);
221	    }
222	
223	    /** The clerk limit in force on a date (null: no limit). */
224	    public BigDecimal clerkLimitOn(LocalDate date) {
225	        return figureOn(CLERK_LIMIT, date);
226	    }
227	
228	    /** The proof threshold in force on a date (null: none). */
229	    public BigDecimal proofThresholdOn(LocalDate date) {
230	        return figureOn(PROOF_THRESHOLD, date);
231	    }
232	
233	    /**
234	     * The proof threshold of a claim of a grade dated {@code date}: the grade's own in force on that
235	     * date when it has one, else the sheet's (null: none).
236	     */
237	    public BigDecimal proofThresholdFor(String grade, LocalDate date) {
238	        BigDecimal own = grade == null ? null : gradeProofThresholdOn(grade, date);
239	        return own != null ? own : proofThresholdOn(date);
240	    }
241	
242	    /**
243	     * Whether a claim of a grade dated {@code date} with a due (null: n/a) needs a proof before it is
244	     * settled or approved: its due is above its proof threshold and it has no proofs, or, while the
245	     * proof kinds are set, none of a kind they list. A due of n/a, or no threshold, needs none.
246	     */
247	    public boolean needsProof(BigDecimal due, String grade, LocalDate date, net.officefloor.hq.app.claim.Claim claim) {
248	        BigDecimal threshold = proofThresholdFor(grade, date);
249	        if (threshold == null || due == null || due.compareTo(threshold) <= 0) return false;
250	        if (claim.getProofs() == 0) return true;
251	        for (String kind : proofKindList()) {
252	            if (claim.proofsOf(kind) == 0) return true;
253	        }
254	        return false;
255	    }
256	
257	    /** The note threshold in force on a date (null: none). */
258	    public BigDecimal noteThresholdOn(LocalDate date) {
259	        return figureOn(NOTE_THRESHOLD, date);
260	    }
261	
262	    /**
263	     * Whether a claim dated {@code date} with a due (null: n/a) and a note needs a note before it is
264	     * opened: its due is above the note threshold in force on its date and its note is empty. A due
265	     * of n/a, or no threshold, needs none.
266	     */
267	    public boolean needsNote(BigDecimal due, LocalDate date, String note) {
268	        BigDecimal threshold = noteThresholdOn(date);
269	        return (note == null || note.isBlank()) && threshold != null && due != null && due.compareTo(threshold) > 0;
270	    }
271	
272	    /** The review threshold in force on a date (null: none). */
273	    public BigDecimal reviewThresholdOn(LocalDate date) {
274	        return figureOn(REVIEW_THRESHOLD, date);
275	    }
276	
277	    /**
278	     * Whether a claim dated {@code date} with a due (null: n/a) goes to REVIEW when it is opened:
279	     * its due is above the review threshold in force on its date. A due of n/a, or no threshold,
280	     * goes straight to OPEN.
281	     */
282	    public boolean needsReview(BigDecimal due, LocalDate date) {
283	        BigDecimal threshold = reviewThresholdOn(date);
284	        return threshold != null && due != null && due.compareTo(threshold) > 0;
285	    }
286	
287	    /** The cap in force on a date (null: none). */
288	    public BigDecimal capOn(LocalDate date) {
289	        return figureOn(CAP, date);
290	    }
291	
292	    /** The rounding mode in force on a date (null: none). */
293	    public RoundingMode roundingOn(LocalDate date) {
294	        String value = valueOn(ROUNDING, date);
295	        if (HALF_UP.equals(value)) return RoundingMode.HALF_UP;
296	        if (HALF_EVEN.equals(value)) return RoundingMode.HALF_EVEN;
297	        return null;
298	    }
299	
300	    /**
301	     * How every figure of a claim that rounds by {@code date} is rounded: by the rounding mode in
302	     * force on that date when there is one, else half up before the policy date ({@code today} when
303	     * it is blank), half to even on or after it.
304	     */
305	    public RoundingMode rounding(LocalDate date, LocalDate today) {
306	        RoundingMode mode = roundingOn(date);
307	        if (mode != null) return mode;
308	        LocalDate policy = policyDate != null ? policyDate : today;
309	        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
310	    }
311	
312	    /** The date of a new claim left undated: the entry date while it is set, else the sheet's today. */
313	    public LocalDate entryDay(LocalDate today) {
314	        return entryDate != null ? entryDate : today;
315	    }
316	
317	    /** Whether a period ending {@code to} is past its grace days on {@code today}: never while they are off. */
318	    public boolean pastGrace(LocalDate to, LocalDate today) {
319	        return graceDays != null && to.plusDays(graceDays).isBefore(today);
320	    }
321	
322	    /** Whether a claim opened on {@code today} is numbered within its period. */
323	    public boolean numbersByPeriod(LocalDate today) {
324	        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
325	    }
326	
327	    /** A person's due-total (null: n/a) held to the cap in force on {@code today}. A due-total of n/a is not capped. */
328	    public BigDecimal capped(BigDecimal dueTotal, LocalDate today) {
329	        BigDecimal cap = capOn(today);
330	        return cap == null || dueTotal == null || dueTotal.compareTo(cap) <= 0 ? dueTotal : cap;
331	    }
332	
333	    /**
334	     * Whether a due (null: n/a) of a claim of a grade is within the clerk limit in force on {@code today}:
335	     * the grade's own when it has one, else the sheet's. A due of n/a is within any limit.
336	     */
337	    public boolean withinClerkLimit(BigDecimal due, String grade, LocalDate today) {
338	        BigDecimal clerkLimit = clerkLimitFor(grade, today);
339	        return clerkLimit == null || due == null || due.compareTo(clerkLimit) <= 0;
340	    }
341	}
342	package net.officefloor.hq.app.person;
343	
344	import java.time.LocalDate;
345	import java.util.ArrayList;
346	import java.util.List;
347	import java.util.Map;
348	import java.util.TreeMap;
349	
350	/** A person on a sheet, as the store holds it. {@code id} is null until first saved. */
351	public class Person {
352	    private Long id;
353	    private final String sheetId;
354	    private String name;
355	    private String grade;
356	    private Integer terms;
357	    private String contact;
358	    private String tags;
359	    private long version;
360	    private int statementCount;
361	    private String statedTotal;
362	    private LocalDate statementDate;
363	    private LocalDate retiredFrom;
364	    private LocalDate addedOn;
365	    private String originSheet;
366	    private String flagReason;
367	    private LocalDate flagUntil;
368	    private String approver;
369	    private final List<Hold> holds = new ArrayList<>();
370	    private final List<Long> patronIds = new ArrayList<>();
371	    private final List<String> aliases = new ArrayList<>();
372	    private final List<PastRetirement> pastRetirements = new ArrayList<>();
373	    private final List<String> snapshots = new ArrayList<>();
374	    private final List<String> statementLines = new ArrayList<>();
375	    private final TreeMap<LocalDate, String> datedGrades = new TreeMap<>();
376	    private final TreeMap<LocalDate, Integer> datedTerms = new TreeMap<>();
377	
378	    public Person(Long id, String sheetId, String name, String grade) {
379	        this(id, sheetId, name, grade, 0);
380	    }
381	
382	    public Person(Long id, String sheetId, String name, String grade, long version) {
383	        this.id = id;
384	        this.sheetId = sheetId;
385	        this.name = name;
386	        this.grade = grade;
387	        this.version = version;
388	    }
389	
390	    public Long getId() { return id; }
391	    public void setId(Long id) { this.id = id; }
392	    public String getSheetId() { return sheetId; }
393	    public String getName() { return name; }
394	    public void setName(String name) { this.name = name; }
395	    /** The first grade they were given: in force from the beginning of time, until their first dated grade. */
396	    public String getGrade() { return grade; }
397	    public void setGrade(String grade) { this.grade = grade; }
398	    /** Their own terms in days from the beginning of time, until their first dated terms; null when they have none. */
399	    public Integer getTerms() { return terms; }
400	    public void setTerms(Integer terms) { this.terms = terms; }
401	    /** The terms recorded from a date, by from-date (null: none): each in force from it until the next. */
402	    public Map<LocalDate, Integer> getDatedTerms() { return datedTerms; }
403	    /** Record the terms (null: none) from this date, replacing any recorded from the same date. */
404	    public void setTermsFrom(Integer terms, LocalDate from) { datedTerms.put(from, terms); }
405	    /**
406	     * Their own terms in force on the date, ahead of their grade's and the sheet's: the latest dated
407	     * ones on or before it, else those from the beginning of time; null when they have none.
408	     */
409	    public Integer termsOn(LocalDate date) {
410	        Map.Entry<LocalDate, Integer> dated = datedTerms.floorEntry(date);
411	        return dated == null ? terms : dated.getValue();
412	    }
413	    /** Their contact, trimmed and lower-cased; null when they have none. */
414	    public String getContact() { return contact; }
415	    public void setContact(String contact) { this.contact = contact; }
416	    /** Their tags: lower-cased, without repeats, sorted and comma separated; null when they have none. */
417	    public String getTags() { return tags; }
418	    public void setTags(String tags) { this.tags = tags; }
419	    /** Their tags, sorted; empty when they have none. */
420	    public List<String> tagList() { return tags == null ? List.of() : List.of(tags.split(",")); }
421	    /** The grades recorded from a date, by from-date: each in force from it until the next. */
422	    public Map<LocalDate, String> getDatedGrades() { return datedGrades; }
423	    /** Record the grade from this date, replacing any recorded from the same date. */
424	    public void setGradeFrom(String grade, LocalDate from) { datedGrades.put(from, grade); }
425	    /** The grade in force on the date: the latest dated one on or before it, else the first grade. */
426	    public String gradeOn(LocalDate date) {
427	        Map.Entry<LocalDate, String> dated = datedGrades.floorEntry(date);
428	        return dated == null ? grade : dated.getValue();
429	    }
430	    /** Raised by one on each save; an edit names the version it was made from. */
431	    public long getVersion() { return version; }
432	    public void setVersion(long version) { this.version = version; }
433	    /** How many statements have been taken for them. */
434	    public int getStatementCount() { return statementCount; }
435	    /** The last statement's due-total (n/a when it had none); null before the first. */
436	    public String getStatedTotal() { return statedTotal; }
437	    /** The sheet's today when the last statement was taken; null before the first. */
438	    public LocalDate getStatementDate() { return statementDate; }
439	    public void setStatements(int count, String statedTotal, LocalDate statementDate) {
440	        this.statementCount = count;
441	        this.statedTotal = statedTotal;
442	        this.statementDate = statementDate;
443	    }
444	    /** The sheet's today when they were added; null when it was not kept (from the beginning of time). */
445	    public LocalDate getAddedOn() { return addedOn; }
446	    public void setAddedOn(LocalDate addedOn) { this.addedOn = addedOn; }
447	    /** The sheet they were transferred from (their latest transfer); null when never transferred. */
448	    public String getOriginSheet() { return originSheet; }
449	    public void setOriginSheet(String originSheet) { this.originSheet = originSheet; }
450	    /** Their flag's reason; null when never flagged. */
451	    public String getFlagReason() { return flagReason; }
452	    /** The date their flag is in force until, inclusive; null when never flagged. */
453	    public LocalDate getFlagUntil() { return flagUntil; }
454	    public void setFlag(String reason, LocalDate until) {
455	        this.flagReason = reason;
456	        this.flagUntil = until;
457	    }
458	    /** The user who may approve or reject their PENDING claims as a steward may; null when none. */
459	    public String getApprover() { return approver; }
460	    public void setApprover(String approver) { this.approver = approver; }
461	    /** Whether {@code user} is their approver. */
462	    public boolean approvedBy(String user) { return approver != null && !approver.isEmpty() && approver.equals(user); }
463	    /** Whether their flag is in force on {@code today}: only a steward may open a claim of theirs. */
464	    public boolean flaggedOn(LocalDate today) {
465	        return flagReason != null && flagUntil != null && today != null && !today.isAfter(flagUntil);
466	    }
467	    /** Whether their flag stops {@code role} opening a claim of theirs on {@code today}. */
468	    public boolean flagRefuses(String role, LocalDate today) {
469	        return flaggedOn(today) && !net.officefloor.hq.app.role.Role.STEWARD.equals(role);
470	    }
471	    /** Whether they had been added by the end of {@code day}. */
472	    public boolean addedBy(LocalDate day) { return addedOn == null || !addedOn.isAfter(day); }
473	    /** The date they are retired from; null when not retired. Set at all, they count as retired. */
474	    public LocalDate getRetiredFrom() { return retiredFrom; }
475	    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }
476	    public boolean isRetired() { return retiredFrom != null; }
477	    /** The retirements they were unretired from, oldest first. */
478	    public List<PastRetirement> getPastRetirements() { return pastRetirements; }
479	    /** Their snapshot lines, oldest first, each as "<the day being left> <due-total>". */
480	    public List<String> getSnapshots() { return snapshots; }
481	    /** Their statements still standing, oldest first (by date), each as "<statement date> <due-total>". */
482	    public List<String> getStatementLines() { return statementLines; }
483	    /** Their holds, in the order added: each from a date to an optional to-date. */
484	    public List<Hold> getHolds() { return holds; }
485	    /** Whether they have any hold at all. */
486	    public boolean isHeld() { return !holds.isEmpty(); }
487	    /** Whether the date is within one of their holds (their claims still count in every total). */
488	    public boolean heldOn(LocalDate date) { return holds.stream().anyMatch((h) -> h.covers(date)); }
489	    /** Whether their retirement date is reached on {@code today}: retired from it or an earlier date. */
490	    public boolean retiredOn(LocalDate today) { return retiredFrom != null && today != null && !today.isBefore(retiredFrom); }
491	    /**
492	     * Whether an OPEN or PENDING claim of theirs on the date, not bound by a statement, counts in no
493	     * total on {@code today}: their retirement date is reached. A hold does not take it out; it only
494	     * takes away their pool cut.
495	     */
496	    public boolean heldOn(LocalDate date, LocalDate today) { return retiredOn(today); }
497	    /** The ids of the people they name as patrons, in the order named. */
498	    public List<Long> getPatronIds() { return patronIds; }
499	    /** Their aliases, trimmed, in the order given: like names, none equal (ignoring case) any name or alias on the sheet. */
500	    public List<String> getAliases() { return aliases; }
501	    /**
502	     * Whether a claim on this date is refused: they are retired from an earlier date, or it is after
503	     * the from and before the to of a past retirement.
504	     */
505	    public boolean retiredBefore(LocalDate date) {
506	        return (retiredFrom != null && date.isAfter(retiredFrom)) || pastRetirements.stream().anyMatch((r) -> r.refuses(date));
507	    }
508	}
509	package net.officefloor.hq.app.person;
510	
511	import java.math.BigDecimal;
512	import java.math.RoundingMode;
513	import java.time.LocalDate;
514	import java.util.ArrayList;
515	import java.util.List;
516	
517	/**
518	 * A person, as the screen reads it (their grade the one in force on the sheet's today), with their statement count, and the last statement's due-total
519	 * and date ("" before the first), whether they are retired and the date they are retired from
520	 * ("" when not), whether they have any hold, their holds (in the order added), the ids of the people they name as patrons (in the order named) with their
521	 * shares (see {@link #shares}), and every
522	 * grade they have been given with the date it is from (the first "", from the beginning of time),
523	 * by from-date, their own terms in days in force on the sheet's today ("" for none), their contact ("" for none), their tags (sorted; none: empty), their aliases
524	 * (in the order given), and whether they clash: their name or an alias is a name or alias on another
525	 * sheet of the sheet's tree, the sheet they were transferred from ("" when never transferred), and
526	 * the retirements they were unretired from, oldest first, each as "<from> to <to>", and their snapshot lines, oldest first, each as
527	 * "<the day being left> <due-total>", and their statements still standing, oldest first (by date), each as
528	 * "<statement date> <due-total>", and their flag's reason while it is in force on the sheet's today ("" otherwise),
529	 * and the user who may approve or reject their PENDING claims as a steward may ("" for none).
530	 */
531	public record PersonResponse(String id, String name, String grade, long version, int statementCount,
532	        String statedTotal, String statementDate, boolean retired, String retiredFrom,
533	        boolean held, List<HoldFrom> holds, java.util.List<String> patronIds, List<String> patronShares, List<GradeFrom> grades, String terms,
534	        String contact, List<String> tags, List<String> aliases, boolean clashing, String origin, List<String> retirements,
535	        List<String> snapshots, List<String> statementLines, String flag,
536	        String approver) {
537	
538	    /** A hold from a date to a date (yyyy-MM-dd; to "" when open-ended), both inclusive. */
539	    public record HoldFrom(String from, String to) {}
540	
541	    /** A grade in force from a date (yyyy-MM-dd; "" from the beginning of time). */
542	    public record GradeFrom(String from, String grade) {}
543	
544	    /**
545	     * The patrons' shares, in the order named: 100.00 split equally among {@code count} patrons, each
546	     * rounded half to even to two decimals, the remainder (100.00 less the shares added up) to the first.
547	     */
548	    static List<String> shares(int count) {
549	        if (count == 0) return List.of();
550	        BigDecimal whole = new BigDecimal("100.00");
551	        BigDecimal each = whole.divide(BigDecimal.valueOf(count), 2, RoundingMode.HALF_EVEN);
552	        List<String> shares = new ArrayList<>();
553	        shares.add(whole.subtract(each.multiply(BigDecimal.valueOf(count - 1))).toPlainString());
554	        for (int i = 1; i < count; i++) shares.add(each.toPlainString());
555	        return shares;
556	    }
557	
558	    /** The person as the screen reads it on the sheet's today: their grade is the one in force on it. */
559	    public static PersonResponse from(Person person, LocalDate today, boolean clashing) {
560	        List<GradeFrom> grades = new ArrayList<>();
561	        grades.add(new GradeFrom("", person.getGrade()));
562	        person.getDatedGrades().forEach((from, grade) -> grades.add(new GradeFrom(from.toString(), grade)));
563	        return new PersonResponse(String.valueOf(person.getId()), person.getName(), person.gradeOn(today),
564	                person.getVersion(), person.getStatementCount(),
565	                person.getStatedTotal() == null ? "" : person.getStatedTotal(),
566	                person.getStatementDate() == null ? "" : person.getStatementDate().toString(),
567	                person.isRetired(), person.getRetiredFrom() == null ? "" : person.getRetiredFrom().toString(),
568	                person.isHeld(),
569	                person.getHolds().stream().map((h) -> new HoldFrom(h.from().toString(), h.to() == null ? "" : h.to().toString())).toList(),
570	                person.getPatronIds().stream().map(String::valueOf).toList(), shares(person.getPatronIds().size()), grades,
571	                person.termsOn(today) == null ? "" : person.termsOn(today).toString(),
572	                person.getContact() == null ? "" : person.getContact(), person.tagList(), List.copyOf(person.getAliases()), clashing,
573	                person.getOriginSheet() == null ? "" : person.getOriginSheet(),
574	                person.getPastRetirements().stream().map((r) -> r.from() + " to " + r.to()).toList(),
575	                List.copyOf(person.getSnapshots()), List.copyOf(person.getStatementLines()),
576	                person.flaggedOn(today) ? person.getFlagReason() : "",
577	                person.getApprover() == null ? "" : person.getApprover());
578	    }
579	}
