42	public class CheckCorrection {
43	    public void check(@Val Claim claim, ClaimRepository repository) throws InvalidClaimException {
44	        String corrects = claim.getCorrects();
45	        if (corrects == null) return;
46	        List<Claim> claims = repository.findByPerson(claim.getSheetId(), claim.getPersonId());
47	        Claim corrected = claims.stream()
48	                .filter((c) -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED)
49	                .findFirst().orElse(null);
50	        if (corrected == null) {
51	            throw new InvalidClaimException("A correction names a settled claim of the same person");
52	        }
53	        // What remains: the target's amount plus the (negative) corrections already made against it.
54	        BigDecimal remaining = corrected.getAmount();
55	        for (Claim other : claims) {
56	            if (claim.getId() != null && Objects.equals(claim.getId(), other.getId())) continue;
57	            if (!corrects.equals(other.getCorrects())) continue;
58	            if (other.getStatus() == ClaimStatus.VOID || other.getStatus() == ClaimStatus.DELETED) continue;
59	            remaining = remaining.add(other.getAmount());
60	        }
61	        if (claim.getAmount().negate().compareTo(remaining) > 0) {
62	            throw new InvalidClaimException("A correction may not exceed what remains of the claim it corrects");
63	        }
64	        // A correction rounds by the date of the claim it corrects.
65	        claim.setCorrectedDate(corrected.getDate());
66	    }
67	}
