76	public class SettleSelectedClaims {
77	    public void settle(@Val Sheet sheet, @Val BulkSettleRequest request, ClaimRepository claims,
78	            PersonRepository people, PeriodRepository periods, SheetRepository sheets, RateRepository rates,
79	            RoleRepository roles, SettingsRepository settings, ClaimLogRepository log, WatchRepository watches, HttpServletRequest http,
80	            Audit audit, Out<BulkSettleResponse> result) {
81	        String user = Audit.user(http);
82	        Set<Long> selected = new HashSet<>();
83	        for (String id : request.claimIds()) {
84	            try {
85	                selected.add(Long.parseLong(id.trim()));
86	            } catch (NumberFormatException | NullPointerException e) {
87	                // not an id: no claim on the sheet, so refused below
88	            }
89	        }
90	        int requested = new HashSet<>(request.claimIds()).size();
91	        int settled = 0;
92	        if (sheet.archived() || Role.VIEWER.equals(roles.roleOf(sheet.id(), user))) {
93	            result.set(new BulkSettleResponse(0, requested)); // a viewer, or an archived sheet, changes nothing
94	            return;
95	        }
96	        // All or nothing: every selected claim is settled in memory first; any refusal refuses them all.
97	        List<Claim> toSettle = new ArrayList<>();
98	        for (Person person : people.findAll(sheet.id())) {
99	            for (Claim claim : claims.findByPerson(sheet.id(), person.getId())) {
100	                if (!selected.contains(claim.getId())) continue;
101	                if (periods.closedOn(sheet.id(), claim.getDueBy()) != null) {
102	                    result.set(new BulkSettleResponse(0, requested));
103	                    return;
104	                }
105	                try {
106	                    SettleClaim.settle(sheet, claim, user, people, rates, roles, settings);
107	                } catch (InvalidClaimStatusException | SelfSettleException e) {
108	                    result.set(new BulkSettleResponse(0, requested));
109	                    return;
110	                }
111	                toSettle.add(claim);
112	            }
113	        }
114	        if (toSettle.isEmpty() || toSettle.size() != requested) {
115	            result.set(new BulkSettleResponse(0, requested)); // a selected id not on the sheet is refused
116	            return;
117	        }
118	        int batch = claims.nextBatch(sheet.id());
119	        BigDecimal total = BigDecimal.ZERO.setScale(2);
120	        Rollup before = rollup(sheet, sheets, people, claims, rates, settings);
121	        for (Claim claim : toSettle) {
122	            claim.setSettleBatch(batch);
123	            claims.save(claim);
124	            log.record(claim, user, sheet.today(), LogClaimStatus.due(sheet, claim, people, rates, settings));
125	            settled++;
126	            if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
127	                total = total.add(claim.getSettledDue());
128	            }
129	            audit.record(AuditClaimStatus.line(sheet, claim, user, people));
130	            WatchNotices.lines(sheet, claim, user, people, watches).forEach(audit::record);
131	            Rollup after = rollup(sheet, sheets, people, claims, rates, settings);
132	            after.changesSince(before, sheet.id(), user).forEach(audit::record);
133	            before = after;
134	        }
135	        audit.record("BATCH_SETTLED sheet=" + sheet.id() + " by=" + user + " batch=" + batch + " count=" + settled
136	                + " total=" + total.setScale(2, RoundingMode.HALF_UP).toPlainString());
137	        result.set(new BulkSettleResponse(settled, requested - settled));
138	    }
139	    private static Rollup rollup(Sheet sheet, SheetRepository sheets, PersonRepository people, ClaimRepository claims,
140	            RateRepository rates, SettingsRepository settings) {
141	        return Rollup.of(sheet.id(), sheets.today(sheet.id()), people, claims, rates, settings.find(sheet.id()));
142	    }
143	}
