403	public class AddPastedClaims {
404	    public void add(@Val Sheet sheet, @Val PasteLines paste, PersonRepository people, ClaimRepository claims,
405	            PeriodRepository periods, RateRepository rates, SettingsRepository settings, ClaimLogRepository log,
406	            ClaimLineRepository claimLines, HolidayRepository holidays, RoleRepository roles, SheetRepository sheets,
407	            HttpServletRequest request, Audit audit, Out<PasteResponse> result)
408	            throws InvalidClaimException, InvalidClaimStatusException, ClosedPeriodException,
409	            RetiredPersonException, ClaimLockedException {
410	        Settings terms = settings.find(sheet.id());
411	        String user = Audit.user(request);
412	        String role = roles.roleOf(sheet.id(), user);
413	        if (!terms.allows("open", role)) throw new InvalidClaimStatusException("A " + role + " may not open a claim");
414	        // Each line resolved against the claims as they stood before the paste.
415	        List<Person> persons = new ArrayList<>();
416	        List<Claim> built = new ArrayList<>();
417	        List<Boolean> existing = new ArrayList<>();
418	        List<Boolean> edited = new ArrayList<>();
419	        Map<Long, List<Claim>> before = new HashMap<>();
420	        Set<Long> taken = new HashSet<>();
421	        Set<String> refs = new HashSet<>();
422	        int number = 0;
423	        for (PasteLine line : paste.lines()) {
424	            number++;
425	            Person person = people.findByName(sheet.id(), line.name());
426	            if (person == null) throw new InvalidClaimException("No one named " + line.name() + " is on the sheet");
427	            if (person.flagRefuses(role, sheet.today())) {
428	                throw new InvalidClaimStatusException("Only a steward may open a claim of " + person.getName() + ": they are flagged");
429	            }
430	            LocalDate date = line.claim().date() == null ? terms.entryDay(sheet.today()) : line.claim().date();
431	            String note = line.claim().note() == null ? "" : line.claim().note();
432	            List<Claim> theirs = before.computeIfAbsent(person.getId(),
433	                    id -> claims.findByPerson(sheet.id(), id));
434	            boolean matched = false;
435	            Claim draft = null;
436	            for (Claim c : theirs) {
437	                if (c.getStatus() == ClaimStatus.VOID || c.getStatus() == ClaimStatus.DELETED) continue;
438	                if (taken.contains(c.getId())) continue;
439	                if (!date.equals(c.getDate())) continue;
440	                if (!note.equals(c.getNote() == null ? "" : c.getNote())) continue;
441	                matched = true;
442	                if (c.getStatus() == ClaimStatus.DRAFT) {
443	                    draft = c; // newest first
444	                    break;
445	                }
446	            }
447	            if (matched && draft == null) {
448	                throw new InvalidClaimException("Line " + number + ": " + line.name() + "'s claim on " + date
449	                        + " is no longer a draft");
450	            }
451	            Claim claim;
452	            if (draft != null) {
453	                claim = draft;
454	                taken.add(claim.getId());
455	                if (claims.lockedByOther(claim, user, sheet.today())) {
456	                    throw new ClaimLockedException(String.valueOf(claim.getId()));
457	                }
458	                new CheckClaimPeriod().check(sheet, claim, periods);
459	                BigDecimal total = claimLines.total(claim);
460	                if (total != null && total.compareTo(line.claim().amount()) != 0) {
461	                    throw new InvalidClaimException("A claim with lines takes their total as its amount");
462	                }
463	                boolean changed = claim.getAmount().compareTo(line.claim().amount()) != 0;
464	                if (changed) {
465	                    claim.setAmount(line.claim().amount());
466	                    claim.setEditedBy(user);
467	                }
468	                existing.add(true);
469	                edited.add(changed);
470	            } else {
471	                claim = new Claim(null, sheet.id(), person.getId(), line.claim().amount(), date, note,
472	                        ClaimStatus.DRAFT, null, null, null);
473	                claim.setRef(line.claim().ref());
474	                if (claim.getRef() != null && !refs.add(claim.getRef().toUpperCase(Locale.ROOT))) {
475	                    throw new InvalidClaimException("The reference " + claim.getRef() + " is pasted more than once");
476	                }
477	                new CheckClaimRef().check(claim, claims);
478	                claim.fixDueBy(terms.termsFor(person, sheet.today()), holidays.dates(sheet.id()));
479	                new CheckClaimPeriod().check(sheet, claim, periods);
480	                claim.setLateEntry(periods.softClosedOn(sheet.id(), claim.getDueBy()) != null);
481	                new CheckClaimRetired().check(sheet, claim, people);
482	                existing.add(false);
483	                edited.add(false);
484	            }
485	            persons.add(person);
486	            built.add(claim);
487	        }
488	        // Then each, in paste order, is saved and opened as the open button opens it.
489	        List<String> lines = new ArrayList<>();
490	        Rollup figures = rollup(sheet, sheets, people, claims, rates, settings);
491	        for (int i = 0; i < built.size(); i++) {
492	            Claim claim = built.get(i);
493	            Person person = persons.get(i);
494	            if (!existing.get(i)) {
495	                claims.save(claim);
496	                log.record(claim, user, sheet.today(), LogClaimStatus.due(sheet, claim, people, rates, settings));
497	                lines.add(ClaimAudit.line("CLAIM_ADDED", sheet, user, person, claim)
498	                        + (claim.getRef() == null ? "" : " ref=" + claim.getRef())
499	                        + (claim.getTags() == null ? "" : " tags=" + claim.getTags()));
500	                if (claim.isLateEntry()) lines.add(ClaimAudit.line("LATE_ENTRY", sheet, user, person, claim));
501	            } else if (edited.get(i)) {
502	                claims.save(claim);
503	                lines.add(ClaimAudit.line("CLAIM_EDITED", sheet, user, person, claim));
504	            }
505	            if (OpenClaim.needsNote(sheet, claim, people, rates, settings)) {
506	                throw new InvalidClaimStatusException(NoteRequired.MESSAGE);
507	            }
508	            Period full = PeriodCaps.full(sheet, claim, periods, claims);
509	            if (full != null) {
510	                throw new InvalidClaimStatusException("Period " + full.name() + " allows at most " + full.cap()
511	                        + " open claims per person");
512	            }
513	            claim.moveTo(OpenClaim.opensTo(sheet, claim, people, rates, settings));
514	            claim.setOpenedBy(user);
515	            if (!claims.markOpened(claim)) throw new InvalidClaimStatusException(ClaimStatus.DRAFT, ClaimStatus.OPEN);
516	            if (claim.getStatus() == ClaimStatus.OPEN) claim.setNumber(ClaimNumbers.next(sheet, claim, terms, periods, claims));
517	            claims.save(claim);
518	            log.record(claim, user, sheet.today(), LogClaimStatus.due(sheet, claim, people, rates, settings));
519	            lines.add(ClaimAudit.line(claim.getStatus().auditEvent(), sheet, user, person, claim));
520	            Rollup after = rollup(sheet, sheets, people, claims, rates, settings);
521	            lines.addAll(after.changesSince(figures, sheet.id(), user));
522	            figures = after;
523	        }
524	        lines.forEach(audit::record);
525	        result.set(new PasteResponse(built.size()));
526	    }
