232	=== TransferPerson
233	/**
234	 * Transfers the person to another sheet (a steward), not retired, and only when their name, aliases
235	 * and contact are free there (their name and aliases on the other sheets of its tree too). They arrive with their grades (and from-dates), terms, contact and
236	 * aliases, and their claims with their status, dates, notes, tags, frozen figures, logs and comments,
237	 * listed in the order they were. Each claim that had a number takes the other sheet's next, in the
238	 * order the claims were opened (by the sheet's today then, then the order added); a correction or
239	 * split names the new numbers. Figures a statement bound are kept, as are their statements (a
240	 * merge on arrival adds their count to the other's), and references and settle batches are not carried. They leave this sheet entirely: patron links
241	 * either way, pool memberships, watches and holds are dropped. When one person on the other sheet
242	 * already has their name or an alias (as names are compared, and not retired), they are then merged into
243	 * that person there, as a merge does (their contact dropped, so it need not be free there).
244	 */
245	public class TransferPerson {
246	    public void transfer(@Val TransferInput input, @Val Sheet sheet, @Val Person person, PersonRepository people,
247	            ClaimRepository claims, SheetRepository sheets, RoleRepository roles, SettingsRepository settings,
248	            PeriodRepository periods, RateRepository rates, HttpServletRequest request, Out<Transfer> transferOut)
249	            throws StewardOnlyException, InvalidPersonException, ViewerException, SheetArchivedException {
250	        String user = Audit.user(request);
251	        if (!Role.STEWARD.equals(roles.roleOf(sheet.id(), user))) {
252	            throw new StewardOnlyException("Only a steward may transfer people");
253	        }
254	        if (person.isRetired()) throw new InvalidPersonException("A retired person cannot be transferred");
255	        Sheet to = sheets.loadOrCreate(input.toSheet());
256	        if (Role.VIEWER.equals(roles.roleOf(to.id(), user))) {
257	            throw new ViewerException("A viewer may not change the sheet transferred to");
258	        }
259	        if (to.archived()) throw new SheetArchivedException(to.id());
260	        java.util.Set<String> toTree = sheets.tree(to.id());
261	        // One already there by their name or an alias: they are merged into that person on arrival.
262	        Person into = null;
263	        List<String> names = new ArrayList<>(List.of(person.getName()));
264	        names.addAll(person.getAliases());
265	        for (String name : names) {
266	            Person found = people.findByName(to.id(), name);
267	            if (found == null) continue;
268	            if (into != null && !into.getId().equals(found.getId())) {
269	                throw new InvalidPersonException("Their names are on more than one person on the sheet transferred to");
270	            }
271	            into = found;
272	        }
273	        if (into != null && into.isRetired()) throw new InvalidPersonException("A retired person cannot be merged");
274	        if (people.nameTakenIn(toTree, person.getName(), person.getId())) {
275	            throw new InvalidPersonException("That name is already on the sheet transferred to");
276	        }
277	        for (String alias : person.getAliases()) {
278	            if (people.nameTakenIn(toTree, alias, person.getId())) {
279	                throw new InvalidPersonException("An alias is already on the sheet transferred to");
280	            }
281	        }
282	        if (into == null && person.getContact() != null && people.contactTaken(to.id(), person.getContact(), null)) {
283	            throw new InvalidPersonException("That contact is already on the sheet transferred to");
284	        }
285	        Settings toSettings = settings.find(to.id());
286	        Rollup toBefore = Rollup.of(to.id(), to.today(), people, claims, rates, toSettings);
287	        // Oldest listed first, so they are listed on the other sheet as they were here.
288	        List<Claim> moving = new ArrayList<>(claims.findByPerson(sheet.id(), person.getId()));
289	        Collections.reverse(moving);
290	        Map<Long, LocalDate> openedOn = new HashMap<>();
291	        List<Claim> numbered = new ArrayList<>();
292	        for (Claim claim : moving) {
293	            if (claim.getNumber() == null) continue;
294	            LocalDate opened = claims.openedOn(claim);
295	            openedOn.put(claim.getId(), opened == null ? claim.getDate() : opened);
296	            numbered.add(claim);
297	        }
298	        numbered.sort(Comparator.comparing((Claim c) -> openedOn.get(c.getId()))
299	                .thenComparing(Claim::getId));
300	        Map<String, String> renumbered = new HashMap<>();
301	        Map<Long, String> numbers = new HashMap<>();
302	        for (Claim claim : numbered) {
303	            String number = ClaimNumbers.next(to, claim, toSettings, periods, claims);
304	            renumbered.put(claim.getNumber(), number);
305	            numbers.put(claim.getId(), number);
306	        }
307	        for (Claim claim : moving) {
308	            claims.transfer(claim, to.id(), numbers.get(claim.getId()),
309	                    claim.getCorrects() == null ? null : renumbered.getOrDefault(claim.getCorrects(), claim.getCorrects()),
310	                    claim.getSplitFrom() == null ? null : renumbered.getOrDefault(claim.getSplitFrom(), claim.getSplitFrom()));
311	        }
312	        people.transfer(person, to.id());
313	        if (into != null) {
314	            Person arrived = people.find(to.id(), person.getId());
315	            List<Claim> merging = new ArrayList<>(claims.findByPerson(to.id(), arrived.getId()));
316	            Collections.reverse(merging);
317	            for (Claim claim : merging) {
318	                claim.mergeTo(into.getId());
319	                claims.save(claim);
320	            }
321	            people.merge(arrived, into);
322	        }
323	        transferOut.set(new Transfer(person, to, toBefore, into));
324	    }
325	}
