387	=== AddImportedPeople
388	/**
389	 * Adds or updates a person per imported line, in order. A line whose name is a person's name or alias on
390	 * the sheet (as names are compared) updates that person as the edit form would: their grade from the
391	 * sheet's today, and their terms and contact when the line gives them. Every other line adds a person.
392	 * Every line is checked first, as the person form checks a person (their name unused on the sheet and
393	 * its tree, their contact unused on the sheet), and a name, person or contact repeated within the import
394	 * is refused too, so a refused import writes nothing; then each person is saved and audited as the form
395	 * does (PERSON_ADDED or PERSON_EDITED), then the figures it moved.
396	 */
397	public class AddImportedPeople {
398	    public void add(@Val Sheet sheet, @Val ImportPeopleLines lines, PersonRepository people, SheetRepository sheets,
399	            ClaimRepository claims, RateRepository rates, SettingsRepository settings, HttpServletRequest request,
400	            Audit audit, Out<ImportPeopleResponse> result)
401	            throws DuplicatePersonNameException, DuplicatePersonContactException, StalePersonException {
402	        record Change(Person person, TermsEdit termsEdit, ContactEdit contactEdit) {}
403	        List<Change> built = new ArrayList<>();
404	        Set<String> names = new HashSet<>();
405	        Set<Long> updatedIds = new HashSet<>();
406	        Set<String> contacts = new HashSet<>();
407	        int added = 0;
408	        int updated = 0;
409	        for (PersonRequest line : lines.lines()) {
410	            if (!names.add(line.name().toLowerCase(Locale.ROOT))) {
411	                throw new DuplicatePersonNameException(line.name());
412	            }
413	            Person person = people.findByName(sheet.id(), line.name());
414	            TermsEdit termsEdit = null;
415	            ContactEdit contactEdit = null;
416	            if (person == null) {
417	                person = new Person(null, sheet.id(), line.name(), line.grade());
418	                person.setTerms(line.termsDays());
419	                person.setContact(line.contactValue());
420	                added++;
421	            } else {
422	                if (!updatedIds.add(person.getId())) throw new DuplicatePersonNameException(line.name());
423	                Integer terms = line.termsDays();
424	                termsEdit = new TermsEdit(terms != null && !terms.equals(person.termsOn(sheet.today())));
425	                if (termsEdit.changed()) person.setTerms(terms);
426	                String contact = line.contactValue();
427	                contactEdit = new ContactEdit(contact != null && !contact.equals(person.getContact()));
428	                if (contact != null) person.setContact(contact);
429	                if (!line.grade().equals(person.gradeOn(sheet.today()))) {
430	                    person.setGradeFrom(line.grade(), sheet.today());
431	                }
432	                updated++;
433	            }
434	            if (person.getContact() != null && !contacts.add(person.getContact())) {
435	                throw new DuplicatePersonContactException(person.getContact());
436	            }
437	            new CheckPersonName().check(person, people, sheets);
438	            new CheckPersonContact().check(person, people);
439	            built.add(new Change(person, termsEdit, contactEdit));
440	        }
441	        String user = Audit.user(request);
442	        Rollup before = Rollup.of(sheet.id(), sheet.today(), people, claims, rates, settings.find(sheet.id()));
443	        for (Change change : built) {
444	            Person person = change.person();
445	            if (person.getId() == null) {
446	                people.save(person);
447	                new AuditPersonAdded().audit(sheet, person, request, audit);
448	            } else {
449	                if (!people.save(person)) throw new StalePersonException(String.valueOf(person.getId()));
450	                new AuditPersonEdited().audit(sheet, person, change.termsEdit(), change.contactEdit(), request, audit);
451	            }
452	            Rollup after = Rollup.of(sheet.id(), sheets.today(sheet.id()), people, claims, rates,
453	                    settings.find(sheet.id()));
454	            after.changesSince(before, sheet.id(), user).forEach(audit::record);
455	            before = after;
456	        }
457	        result.set(new ImportPeopleResponse(added, updated));
458	    }
459	}
