461	/**
462	 * Splits the import into lines (blank lines skipped) and checks each by the person form's rules; the
463	 * first line that fails refuses the whole import. An import with no lines is refused too. A line with
464	 * a blank grade takes the sheet's default grade.
465	 */
466	public class ValidateImportPeople {
467	    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ImportPeopleRequest request,
468	            SettingsRepository settings, Out<ImportPeopleLines> linesOut)
469	            throws InvalidPersonException {
470	        String text = request == null || request.text() == null ? "" : request.text();
471	        List<PersonRequest> lines = new ArrayList<>();
472	        int number = 0;
473	        String defaultGrade = null;
474	        for (String raw : text.split("\\r?\\n|\\r")) {
475	            number++;
476	            if (raw.isBlank()) continue;
477	            String[] fields = raw.split(",", 4);
478	            if (fields.length < 2) throw new InvalidPersonException("Line " + number + ": name,grade,terms,contact");
479	            String terms = fields.length > 2 ? fields[2] : "";
480	            String contact = fields.length > 3 ? fields[3] : "";
481	            String grade = fields[1];
482	            if (grade.isBlank()) {
483	                if (defaultGrade == null) defaultGrade = settings.find(sheetId).newPersonGrade();
484	                grade = defaultGrade;
485	            }
486	            try {
487	                lines.add(PersonRequest.checked(new PersonRequest(fields[0], grade, null, "", terms, contact, null, "")));
488	            } catch (InvalidPersonException e) {
489	                throw new InvalidPersonException("Line " + number + ": " + e.getMessage());
490	            }
491	        }
492	        if (lines.isEmpty()) throw new InvalidPersonException("Paste at least one line of name,grade,terms,contact");
493	        linesOut.set(new ImportPeopleLines(lines));
494	    }
495	}
