497	/**
498	 * Gives each selected person, in list order (the order they were added), the grade from the
499	 * from-date exactly as the person form would (see {@link ApplyPerson}): their name and terms are
500	 * kept, and a grade left as the row shows it with the from-date blank records nothing. Each is
501	 * audited as a single edit is: its PERSON_EDITED line, then the figures it moved. A viewer, or anyone
502	 * on an archived sheet, has every selected person refused: none is graded and nothing is written.
503	 */
504	public class GradeSelectedPeople {
505	    public void grade(@Val Sheet sheet, @Val BulkGradeRequest request, PersonRepository people,
506	            ClaimRepository claims, RateRepository rates, SettingsRepository settings, RoleRepository roles, HttpServletRequest http,
507	            Audit audit, Out<BulkGradeResponse> result) {
508	        String user = Audit.user(http);
509	        if (sheet.archived() || Role.VIEWER.equals(roles.roleOf(sheet.id(), user))) {
510	            result.set(new BulkGradeResponse(0));
511	            return;
512	        }
513	        Set<Long> selected = new HashSet<>();
514	        for (String id : request.personIds()) {
515	            try {
516	                selected.add(Long.parseLong(id.trim()));
517	            } catch (NumberFormatException | NullPointerException e) {
518	                // not an id: no person on the sheet
519	            }
520	        }
521	        boolean dated = !request.gradeFrom().isEmpty();
522	        Rollup before = rollup(sheet, people, claims, rates, settings);
523	        int graded = 0;
524	        for (Person person : people.findAll(sheet.id())) {
525	            if (!selected.contains(person.getId())) continue;
526	            if (dated || !request.grade().equals(person.gradeOn(sheet.today()))) {
527	                person.setGradeFrom(request.grade(), dated ? LocalDate.parse(request.gradeFrom()) : sheet.today());
528	            }
529	            // Saved over by someone else since it was read: left as it is.
530	            if (!people.save(person)) continue;
531	            graded++;
532	            audit.record("PERSON_EDITED sheet=" + sheet.id() + " by=" + user + " name=" + person.getName()
533	                    + " grade=" + person.gradeOn(sheet.today()));
534	            Rollup after = rollup(sheet, people, claims, rates, settings);
535	            after.changesSince(before, sheet.id(), user).forEach(audit::record);
536	            before = after;
537	        }
538	        result.set(new BulkGradeResponse(graded));
539	    }
540	    private static Rollup rollup(Sheet sheet, PersonRepository people, ClaimRepository claims, RateRepository rates,
541	            SettingsRepository settings) {
542	        return Rollup.of(sheet.id(), sheet.today(), people, claims, rates, settings.find(sheet.id()));
543	    }
544	}
