=== pool/SavePoolMember
/**
 * A pool or person not on the sheet, or a person already in the pool, is refused. A member pool is
 * refused when it is the pool itself, is already a member of a pool, contains the pool through any
 * chain, or would make a chain of pools more than three deep.
 */
public class SavePoolMember {
    static final int MAX_DEPTH = 3;
    public void save(@Val PoolMemberInput input, @Val Sheet sheet, PoolRepository pools, PersonRepository people,
            Out<PoolMember> memberOut) throws InvalidPoolException {
        Pool pool = pools.find(sheet.id(), input.pool());
        if (pool == null) throw new InvalidPoolException("No pool " + input.pool());
        if (input.memberPool() != null) {
            Pool member = pools.find(sheet.id(), input.memberPool());
            if (member == null) throw new InvalidPoolException("No pool " + input.memberPool());
            if (member.id().equals(pool.id())) throw new InvalidPoolException("A pool cannot contain itself");
            if (pools.parentOf(member) != null) {
                throw new InvalidPoolException(member.name() + " is already a member of a pool");
            }
            int level = 1;
            for (Pool above = pools.parentOf(pool); above != null; above = pools.parentOf(above)) {
                if (above.id().equals(member.id())) throw new InvalidPoolException("A pool cannot contain itself");
                level++;
            }
            if (level + height(member, pools) > MAX_DEPTH) {
                throw new InvalidPoolException("A chain of pools is at most " + MAX_DEPTH + " deep");
            }
            pools.addMemberPool(pool, member, input.share(), input.from(), input.to());
            memberOut.set(new PoolMember(sheet.id(), pool.name(), null, member.name(), member.name(), input.share(),
                    false, false, input.from(), input.to(), PoolMember.covers(input.from(), input.to(), sheet.today())));
            return;
        }
        Person person = people.find(sheet.id(), input.personId());
        if (person == null) throw new InvalidPoolException("No such person");
        if (pools.isMember(pool, person.getId())) {
            throw new InvalidPoolException(person.getName() + " is already in " + pool.name());
        }
        pools.addMember(pool, person.getId(), input.share(), input.from(), input.to());
        memberOut.set(new PoolMember(sheet.id(), pool.name(), person.getId(), null, person.getName(), input.share(),
                person.isRetired(), person.getHolds().stream().anyMatch(h -> h.covers(sheet.today())), input.from(), input.to(),
                PoolMember.covers(input.from(), input.to(), sheet.today())));
    }
    /** How many pools deep the chain below this pool goes, the pool itself counting as one. */
    private static int height(Pool pool, PoolRepository pools) {
        int below = 0;
        for (Pool m : pools.memberPools(pool)) below = Math.max(below, height(m, pools));
        return 1 + below;
    }
}
=== pool/ValidatePoolMember
/** A member needs a pool, a person or a member pool, and a share with at most two decimals, more than 0.00 and at most 100.00;
 * optional from- and to-dates, a to-date before the from-date refused. */
public class ValidatePoolMember {
    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
    public void validate(@RequestBody PoolMemberRequest request, Out<PoolMemberInput> body) throws InvalidPoolException {
        if (request == null) throw new InvalidPoolException("A pool member is required");
        String pool = request.pool() == null ? "" : request.pool().trim();
        if (pool.isEmpty()) throw new InvalidPoolException("A pool is required");
        String memberPool = request.memberPool() == null ? "" : request.memberPool().trim();
        Long personId = null;
        if (memberPool.isEmpty()) {
            try {
                personId = Long.parseLong(request.personId() == null ? "" : request.personId().trim());
            } catch (NumberFormatException e) {
                throw new InvalidPoolException("A person or a pool is required");
            }
        }
        String text = request.share() == null ? "" : request.share().trim();
        if (!text.matches("\\d+(\\.\\d{1,2})?")) throw new InvalidPoolException("A share is a number with at most two decimals");
        BigDecimal share = new BigDecimal(text).setScale(2);
        if (share.signum() <= 0 || share.compareTo(HUNDRED) > 0) {
            throw new InvalidPoolException("A share is more than 0.00 and at most 100.00");
        }
        LocalDate from = date(request.from(), "A from-date is a date");
        LocalDate to = date(request.to(), "A to-date is a date");
        if (from != null && to != null && to.isBefore(from)) {
            throw new InvalidPoolException("A to-date is not before the from-date");
        }
        body.set(new PoolMemberInput(pool, personId, memberPool.isEmpty() ? null : memberPool, share, from, to));
    }
    private static LocalDate date(String value, String message) throws InvalidPoolException {
        String raw = value == null ? "" : value.trim();
        if (raw.isEmpty()) return null;
        try {
            return LocalDate.parse(raw);
        } catch (DateTimeParseException e) {
            throw new InvalidPoolException(message);
        }
    }
}
